cat <<'EOF' | agent-browser --session amazon eval --stdin 2>&1
const items = document.querySelectorAll('[data-component-type="s-search-result"]');
let out = [];
for (let i=0; i<Math.min(3, items.length); i++){
  const it = items[i];
  const title = it.querySelector('h2')?.innerText || '';
  const link = it.querySelector('h2 a, a.a-link-normal.s-link-style')?.href || it.querySelector('a')?.href || '';
  const price = it.querySelector('.a-price .a-offscreen')?.innerText || '';
  const format = it.querySelector('.a-color-secondary .a-size-base')?.innerText || '';
  out.push({i, title, price, link: link.split('/ref')[0]});
}
JSON.stringify(out, null, 2);
EOF

